#include <iostream>
#include <vector>
#include <string>

std::vector<std::string> namen = {"Anna", "Ben", "Clara"};
for (const auto& name : namen) {
    std::cout << name << std::endl;
}

for (char buchstabe : std::string("Hallo")) {
    std::cout << buchstabe << std::endl;
}

for (int i = 0; i < 5; i++) {
    std::cout << i;      // 0 1 2 3 4
}

for (int i = 0; i < 10; i += 2) {
    std::cout << i;      // 0 2 4 6 8
}

std::vector<int> zahlen = {10, 20, 30};
for (int i = 0; i < (int)zahlen.size(); i++) {
    std::cout << i << ": " << zahlen[i];
}

int versuche = 0;
int eingabe;
while (true) {
    std::cin >> eingabe;
    versuche++;
    if (eingabe == 42) {
        std::cout << "Richtig!";
        break;
    }
    if (versuche >= 3) break;
}

for (int i = 0; i < 10; i++) {
    if (i % 2 == 0) continue;   // nächste Runde
    std::cout << i;             // ungerade Zahlen
}
